        try { v = (typeof window !== 'undefined' && window.__XZ_CARD_VER__) || ''; } catch (eV1) { v = ''; }
        if (!v) { try { v = (window.top && window.top.__XZ_CARD_VER__) || ''; } catch (eV2) { v = ''; } }
