            d += 'C' + (p1[0] + (p2[0] - p0[0]) / 6 * t).toFixed(1) + ' ' + (p1[1] + (p2[1] - p0[1]) / 6 * t).toFixed(1)
                + ' ' + (p2[0] - (p3[0] - p1[0]) / 6 * t).toFixed(1) + ' ' + (p2[1] - (p3[1] - p1[1]) / 6 * t).toFixed(1)
