    /* <<<XZ_MAP_CORE_END>>> */

    function pageMap() {
        var here = xzMapHereParts();
        var inState = !!state.mapRegion;
        var view = xzMapRender(state.mapRegion || '', state.mapPick || '', state.mapAreaPick || '');
        var reg = view.reg;
        var zoomed = !!view.zoomed;
        var litCount = XZ_MAP_STATES.length - XZ_MAP_STATES.filter(function (r) {
            return r.fog && here.state !== r.n;
        }).length;

        /* ★ v307：只显示「点中的那一个」。
           原来这里把九州九域 + 乱魔海整段全列出来，一屏全是卡片 ——
           玩家点地图本就是想看某一个地方，列全等于让人自己在里面找。
           现在的口径：点过谁显示谁；没点过显示「当前所在」；都没有才给一句提示。
           ★ v310：判定逻辑已挪进 xzMapInfoTarget()（多了地点/人物两层，堆在页面函数里太乱）。 */

        var h = '<div class="xz-tianji-box">';
        h += '<div class="xz-tianji-title"><span>🗺️</span><span>三州 · ' + (inState ? esc(reg.n) : '舆图') + '</span>';
        /* ★★★ v330【用户：「地图加一个按钮返回上一层，而不是直接只能返回九州大地图」】★★★
           舆图其实有**四层**：九州全图 → 州 → 域 → 地点/人物（v310 把百科并进来之后才凑齐）。
           旧按钮只有「◀ 九州」一条，从「某个人物的资料卡」一路回全图要连点三次空白，
           而且每点一次都不知道自己刚才在哪一层。
           ⇒ 一颗「◀ 上一层」：按**深度**退一格（人物→地点→域→州→全图），
             只有真的在某一层里才出现；全图状态不显示（那时没有"上一层"可回）。
           ⚠ 判据必须把这五个字段**全算进去**：只判 mapRegion 的话，
             人物卡（mapWho 有值、mapRegion 也有值）按一下会直接跳回九州 —— 又变成旧行为。 */
        var _mapDepth = xzMapDepthOf(state);
        if (_mapDepth > 0) {
            h += '<button type="button" class="xz-tianji-goto-btn" data-xz-act="map-up" style="margin-left:8px;padding:2px 9px;font-size:11px;" title="退回上一级（州 → 域 → 地点 → 人物 逐级往回）">◀ 上一层</button>';
        }
        h += '<span style="font-size:11px;color:var(--xz-muted);margin-left:auto;">' +
             (inState ? '点域放大' : '点州放大') + '</span></div>';

        h += '<div class="xz-map-hint">当前所在：<b>' + esc(here.raw || '三州') + '</b>';
        if (!inState) h += '　｜　已勘明 <b>' + litCount + ' / ' + XZ_MAP_STATES.length + '</b> 州';
        if (state.mapNotice) h += '<div style="color:#f0a3a3;margin-top:4px;">' + esc(state.mapNotice) + '</div>';
        h += '</div>';

        /* ── ★★★ v464：「地点」搬进舆图（用户：「地点塞进舆图」）★★★ ──
           它原来挂在状态栏顶栏的右栏（`.xz-place-col`），立绘块一删就跟着消失。
           ⚠ 位置**必须在画布之前**。第一版放在画布之后（原注释还写了理由：
             "放上面会把人推到点地图之前"），结果真 Chrome 实测：画布固定高、
             直接把这块挤到首屏之外 —— 玩家进舆图页**根本看不见地点**，
             要往下滚才有。判据只量了 getBoundingClientRect 有尺寸就过了，
             是截图才看出来「它不在屏幕上」。这段与「当前所在 / 已勘明 N 州」
             同属一条"我在哪"的情报线，紧跟其后才连贯。
           ⚠ 全项目只有这一处调用；状态栏那边已经没有任何 `.xz-place-col`。 */
        h += xzSectSideHtml();

        /* 地图画布：svg 只画地形与分区，文字是覆盖在上面的 HTML（见 xzMapRender 的说明） */
        h += '<div class="xz-map-canvas' + (zoomed ? ' is-zoom' : '') + '">' + view.svg;
        view.labels.forEach(function (L) {
            h += '<div class="xz-map-label ' + L.cls + '" style="left:' + L.l + '%;top:' + L.t + '%;">' + esc(L.txt) + '</div>';
        });
        h += '</div>';

        /* ── 单张资料卡（★ v310：地点与人物也在这里展列，百科页随之删除）──
           口径：卡片永远只有一张，内容按「点中的粒度」决定 ——
           州 → 域 → 地点 → 人物，一层层往下展，不叠第二张卡。 */
        var info = xzMapInfoTarget(here);
        if (!info) {
            h += '<div class="xz-map-info is-empty">' +
                 (inState ? '点地图上的任意一域，看它下辖的地点与人物。' : '点地图上的任意一州，放大看它的域、地点与人物。') +
                 '</div>';
        } else {
            h += '<div class="xz-map-info">';
            if (info.kind === 'state') {
                h += '<div class="xz-map-info-top"><span class="xz-map-info-name">' + esc(info.s.n) + '</span>' +
                     '<span class="xz-map-info-meta">' + esc(info.s.own) + '</span>' +
                     '<span class="xz-map-info-n">' + info.s.areas.length + ' 域</span>' +
                     (here.state === info.s.n ? '<span class="xz-map-here-tag">在此</span>' : '') + '</div>';
                h += '<div class="xz-map-info-note">' + esc(info.s.note) + '</div>';
                h += '<div class="xz-map-chips">';
                info.s.areas.forEach(function (a) {
                    h += '<span class="xz-map-chip is-link" data-xz-act="map-focus-area" data-map-region="' + esc(info.s.n) + '" data-map-area="' + esc(a.n) + '">'
                        + '<b>' + esc(a.n) + '</b><i>' + esc(a.kind) + '</i></span>';
                });
                h += '</div>';
                h += '<div class="xz-map-info-actions">';
                h += '<button type="button" class="xz-map-info-btn" data-xz-act="map-enter" data-map-region="' + esc(info.s.n) + '">进入此州 ▸</button>';
                /* ★ v330：这里改成「一步回全图」，与标题栏那颗「◀ 上一层」分工明确：
                     上一层 = 退一格（人物→地点→域→州）；回全图 = 一次清空。
                   旧标签「缩回全图」在州内层读起来像"缩回上一级"，实际却不清州 ——
                   名不副实比没有更坑。 */
                if (zoomed) h += '<button type="button" class="xz-map-info-btn is-ghost" data-xz-act="map-zoomout">⤢ 回全图</button>';
                h += '</div>';
            } else if (info.kind === 'area') {
                h += '<div class="xz-map-info-top"><span class="xz-map-info-name">' + esc(info.a.n) + '</span>' +
                     '<span class="xz-map-info-meta">' + esc(info.a.kind) + '　·　' + esc(info.s.n) + '</span>' +
                     (here.area === info.a.n ? '<span class="xz-map-here-tag">在此</span>' : '') + '</div>';
                h += '<div class="xz-map-info-note">' + esc(info.a.note) + '</div>';
                h += '<div class="xz-map-chips">';
                info.a.cities.forEach(function (c) {
                    h += '<span class="xz-map-chip is-link" data-xz-act="map-focus-place" data-map-region="' + esc(info.s.n) + '" data-map-area="' + esc(info.a.n) + '" data-map-place="' + esc(c.n) + '">'
                        + '<b>' + esc(c.n) + '</b><i>' + esc(c.t) + '</i></span>';
                });
                h += '</div>';
            } else {
                /* ── 地点详细：地名 / 类别 / 说明 / 相关人物（人物可继续点） ── */
                h += '<div class="xz-map-info-top"><span class="xz-map-info-name">' + esc(info.c.n) + '</span>' +
                     '<span class="xz-map-info-meta">' + esc(info.c.t) + '</span>' +
                     (here.city === info.c.n ? '<span class="xz-map-here-tag">在此</span>' : '') + '</div>';
                h += '<div class="xz-map-info-note">' + esc(info.c.d) + '</div>';
                h += '<div class="xz-map-info-crumb">' + esc(info.s.n) + ' · ' + esc(info.a.n) + '</div>';
                var pf = info.c.f || [];
                if (pf.length) {
                    h += '<div class="xz-map-info-sub">相关人物</div><div class="xz-map-chips">';
                    pf.forEach(function (nm) {
                        h += '<span class="xz-map-chip is-link is-who" data-xz-act="map-focus-who" data-map-who="' + esc(nm) + '">' + esc(nm) + '</span>';
                    });
                    h += '</div>';
                }
                h += '<div class="xz-map-info-actions">' +
                     '<button type="button" class="xz-map-info-btn is-ghost" data-xz-act="map-clear-place">◀ 返回本域</button>' +
                     '<button type="button" class="xz-map-info-btn" data-xz-goto="' + esc(info.c.n) + '">前往此地 ➔</button>' +
                     '</div>';
            }
            h += '</div>';
        }

        /* ── 人物卡：从地点里的「相关人物」点进来 ──
           数据优先取**变量人物列表**（剧情里活着的那个），取不到才退回百科参考表 ——
           只认静态表的话，改过名字/涨过境界的 NPC 会一直显示旧值。 */
        if (state.mapWho) {
            var pe = xzMapPersonOf(state.mapWho);
            h += '<div class="xz-map-info is-who">';
            h += '<div class="xz-map-info-top"><span class="xz-map-info-name">' + esc(state.mapWho) + '</span>' +
                 (pe.realm ? '<span class="xz-map-info-meta">' + esc(pe.realm) + '</span>' : '') +
                 (pe.source === 'var' ? '<span class="xz-map-info-n">在场人物</span>' : '') + '</div>';
            if (pe.org) h += '<div class="xz-map-info-crumb">' + esc(pe.org) + '</div>';
            if (pe.desc) h += '<div class="xz-map-info-note">' + esc(pe.desc) + '</div>';
            h += '<div class="xz-map-info-actions">' +
                 '<button type="button" class="xz-map-info-btn is-ghost" data-xz-act="map-clear-who">✕ 收起人物</button></div>';
            h += '</div>';
        }

        h += '</div>';
        return h;
    }

    /* ══ 舆图资料卡的取数：优先取「精确的选中」，没有就退回「当前所在」 ══
       原来的 pageMap 把这段判定写在渲染里（pickState/pickArea 两个局部变量），
       加上地点与人物之后分支变多，再堆在页面函数里就成了一团 —— 抽出来单独一处。 */
    function xzMapInfoTarget(here) {
        var inState = !!state.mapRegion;
        if (!inState) {
            var want = state.mapPick || here.state;
            var ps = null;
            XZ_MAP_STATES.forEach(function (r) {
                if (r.n === want && (!r.fog || here.state === r.n)) ps = r;
            });
            return ps ? { kind: 'state', s: ps } : null;
        }
        var reg = null;
        XZ_MAP_STATES.forEach(function (r) { if (r.n === state.mapRegion) reg = r; });
        if (!reg) return null;
        var wantA = state.mapAreaPick || here.area;
        var pa = null;
        reg.areas.forEach(function (a) { if (a.n === wantA) pa = a; });
        if (!pa) return null;
        /* 再往下一层：点中的地点 */
        if (state.mapPlace) {
            var pc = null;
            pa.cities.forEach(function (c) { if (c.n === state.mapPlace) pc = c; });
            if (pc) return { kind: 'place', s: reg, a: pa, c: pc };
        }
        return { kind: 'area', s: reg, a: pa };
    }

    /* 人物资料：先查变量（在场/在册的那个），再退回百科参考表。
       ⚠ 参考表的 realm 是**当年写死的**，变量里的才是活的 —— 所以变量优先。 */
    function xzMapPersonOf(nm) {
        var out = { realm: '', org: '', desc: '', source: 'dict' };
        try {
            var p = (getVariables() || {}).人物列表 || {};
            var hit = p[nm];
            if (hit && (hit.境界 || hit.外貌 || hit.种族)) {
                out.realm = String(hit.境界 || '');
                out.desc = String(hit.外貌 || '');
                /* 在场人物的「所属」没存字段，只能靠人设参考表补 —— 取不到就空着，不编 */
                PERSON_DICT.forEach(function (d) { if (d.name === nm) out.org = d.org; });
                out.source = 'var';
                return out;
            }
        } catch (eV) {}
        PERSON_DICT.forEach(function (d) {
            if (d.name === nm) {
                out.realm = d.realm; out.org = d.org; out.desc = (d.org ? d.desc : d.desc);
                out.source = 'dict';
            }
        });
        return out;
    }

    /* ═══ v310：百科页已删除（用户：「百科可以删掉了，反正有地图了」）═══
       原来的 pageWiki 只做「查地名、查人物」两件事，而舆图现在能做到更好：
       点州 → 域 → 地点 → 相关人物，一路点下去，还带「前往此地」。
       参考表 PERSON_DICT 保留 —— 舆图的人物卡拿它补「所属」这类静态资料，
       变量里的人（活的那个）优先，取不到才退回这里。
       ★ v397b：PLACE_DICT 已删（零读取）。见上方 xzWikiTopHtml 那段注释的说明。 */
    /* 旧址留一句说明即可，函数体不保留：留着死代码，下一个读代码的人会以为还有一条路径。 */

